var DY = 20;
var DX = DY * 0.5 * sqrt(3);

//let COLOR1 = "#FF99CC";
//let COLOR2 = "#99CCFF";
//let COLOR3 = "#CCFF99";
var COLOR1 = "#99CCFF";
var COLOR2 = "#99CCFF";
var COLOR3 = "#99CCFF";

/*
 u   v
  \ /
   |
   w
*/
function hexVertex(u, v, w) {
  vertex((v - u) * DX, (w - 0.5 * (u + v)) * DY);
}

function hexTranslate(u, v, w) {
  translate((v - u) * DX, (w - 0.5 * (u + v)) * DY);
}

function drawBlock(a, b, c, col) {
  let d = 0 - a;
  let e = 1 - b;
  let f = 2 - c;

  /*
     /|
    / /
   | |
   |/
  */
  fill(lerpColor(col, "#000000", 0.667));
  beginShape();
  hexVertex(0, 0, 0);
  hexVertex(d, f, d);
  hexVertex(d, f, e);
  hexVertex(d, e, e);
  hexVertex(d, e, f);
  hexVertex(d, d, f);
  endShape(CLOSE);

  /*
   |\
    \ \
     | |
      \|
  */
  fill(lerpColor(col, "#000000", 0.333));
  beginShape();
  hexVertex(0, 0, 0);
  hexVertex(d, d, f);
  hexVertex(e, d, f);
  hexVertex(e, d, e);
  hexVertex(f, d, e);
  hexVertex(f, d, d);
  endShape(CLOSE);

  /*
   /\/\
   \  /
    \/
  */
  fill(col);
  beginShape();
  hexVertex(0, 0, 0);
  hexVertex(f, d, d);
  hexVertex(f, e, d);
  hexVertex(e, e, d);
  hexVertex(e, f, d);
  hexVertex(d, f, d);
  endShape(CLOSE);
}

function setup() {
  createCanvas(400, 400);
}

function draw() {
  let t = millis() * 1e-3;
  let a = sin(t - 2 * THIRD_PI) / 3;
  let b = sin(t) / 3;
  let c = sin(t + 2 * THIRD_PI) / 3;
  noStroke();
  hexTranslate(t % 9, 0, 0);
  for (let i = 0; i < 3; i++) {
    pushMatrix();
    for (let j = 0; j < 6; j++) {
      pushMatrix();
      drawBlock(a, b, c, COLOR1);
      hexTranslate(-3, 0, 0);
      drawBlock(b, c, a, COLOR2);
      hexTranslate(0, -3, 0);
      drawBlock(c, a, b, COLOR3);
      hexTranslate(-3, 0, 0);
      drawBlock(a, b, c, COLOR1);
      hexTranslate(0, -3, 0);
      drawBlock(b, c, a, COLOR2);
      hexTranslate(-3, 0, 0);
      drawBlock(c, a, b, COLOR3);
      popMatrix();
      hexTranslate(-3, +3, 0);
    }
    popMatrix();
    hexTranslate(0, 0, 9);
  }
}
